while_loop.code:
count = 0;
while (count < 5)
  disp(count);
  count++; # Auto-increment supported
endwhile

functions.code:
function [mean_val, std_val] = get_stats(data)
  if (isempty(data))
    mean_val = NA;
    std_val = NA;
    return;
  endif
  mean_val = mean(data);
  std_val = std(data);
endfunction

